  1	/**
  2	 * jQuery json-viewer
  3	 * @author: Alexandre Bodelot <alexandre.bodelot@gmail.com>
  4	 * @link: https://github.com/abodelot/jquery.json-viewer
  5	 */
  6	(function($) {
  7	
  8	  /**
  9	   * Check if arg is either an array with at least 1 element, or a dict with at least 1 key
 10	   * @return boolean
 11	   */
 12	  function isCollapsable(arg) {
 13	    return arg instanceof Object && Object.keys(arg).length > 0;
 14	  }
 15	
 16	  /**
 17	   * Check if a string represents a valid url
 18	   * @return boolean
 19	   */
 20	  function isUrl(string) {
 21	    var urlRegexp = /^(https?:\/\/|ftps?:\/\/)?([a-z0-9%-]+\.){1,}([a-z0-9-]+)?(:(\d{1,5}))?(\/([a-z0-9\-._~:/?#[\]@!$&'()*+,;=%]+)?)?$/i;
 22	    return urlRegexp.test(string);
 23	  }
 24	
 25	 /**
 26	  * Return the input string html escaped
 27	  * @return string
 28	  */
 29	  function htmlEscape(s) {
 30	    return s.replace(/&/g, '&amp;')
 31	      .replace(/</g, '&lt;')
 32	      .replace(/>/g, '&gt;')
 33	      .replace(/'/g, '&apos;')
 34	      .replace(/"/g, '&quot;')
 35	  }
 36	
 37	  /**
 38	   * Transform a json object into html representation
 39	   * @return string
 40	   */
 41	  function json2html(json, options) {
 42	    var html = '';
 43	    if (typeof json === 'string') {
 44	      // Escape tags and quotes
 45	      json = htmlEscape(json)
 46	
 47	      if (options.withLinks && isUrl(json)) {
 48	        html += '<a href="' + json + '" class="json-string" target="_blank">' + json + '</a>';
 49	      } else {
 50	        // Escape double quotes in the rendered non-URL string.
 51	        json = json.replace(/&quot;/g, '\\&quot;');
 52	        html += '<span class="json-string">"' + json + '"</span>';
 53	      }
 54	    } else if (typeof json === 'number') {
 55	      html += '<span class="json-literal">' + json + '</span>';
 56	    } else if (typeof json === 'boolean') {
 57	      html += '<span class="json-literal">' + json + '</span>';
 58	    } else if (json === null) {
 59	      html += '<span class="json-literal">null</span>';
 60	    } else if (json instanceof Array) {
 61	      if (json.length > 0) {
 62	        html += '[<ol class="json-array">';
 63	        for (var i = 0; i < json.length; ++i) {
 64	          html += '<li>';
 65	          // Add toggle button if item is collapsable
 66	          if (isCollapsable(json[i])) {
 67	            html += '<a href class="json-toggle"></a>';
 68	          }
 69	          html += json2html(json[i], options);
 70	          // Add comma if item is not last
 71	          if (i < json.length - 1) {
 72	            html += ',';
 73	          }
 74	          html += '</li>';
 75	        }
 76	        html += '</ol>]';
 77	      } else {
 78	        html += '[]';
 79	      }
 80	    } else if (typeof json === 'object') {
 81	      var keyCount = Object.keys(json).length;
 82	      if (keyCount > 0) {
 83	        html += '{<ul class="json-dict">';
 84	        for (var key in json) {
 85	          if (Object.prototype.hasOwnProperty.call(json, key)) {
 86	            key = htmlEscape(key);
 87	            var keyRepr = options.withQuotes ?
 88	              '<span class="json-string">"' + key + '"</span>' : key;
 89	
 90	            html += '<li>';
 91	            // Add toggle button if item is collapsable
 92	            if (isCollapsable(json[key])) {
 93	              html += '<a href class="json-toggle">' + keyRepr + '</a>';
 94	            } else {
 95	              html += keyRepr;
 96	            }
 97	            html += ': ' + json2html(json[key], options);
 98	            // Add comma if item is not last
 99	            if (--keyCount > 0) {
100	              html += ',';
101	            }
102	            html += '</li>';
103	          }
104	        }
105	        html += '</ul>}';
106	      } else {
107	        html += '{}';
108	      }
109	    }
110	    return html;
111	  }
112	
113	  /**
114	   * jQuery plugin method
115	   * @param json: a javascript object
116	   * @param options: an optional options hash
117	   */
118	  $.fn.jsonViewer = function(json, options) {
119	    // Merge user options with default options
120	    options = Object.assign({}, {
121	      collapsed: false,
122	      rootCollapsable: true,
123	      withQuotes: false,
124	      withLinks: true
125	    }, options);
126	
127	    // jQuery chaining
128	    return this.each(function() {
129	
130	      // Transform to HTML
131	      var html = json2html(json, options);
132	      if (options.rootCollapsable && isCollapsable(json)) {
133	        html = '<a href class="json-toggle"></a>' + html;
134	      }
135	
136	      // Insert HTML in target DOM element
137	      $(this).html(html);
138	      $(this).addClass('json-document');
139	
140	      // Bind click on toggle buttons
141	      $(this).off('click');
142	      $(this).on('click', 'a.json-toggle', function() {
143	        var target = $(this).toggleClass('collapsed').siblings('ul.json-dict, ol.json-array');
144	        target.toggle();
145	        if (target.is(':visible')) {
146	          target.siblings('.json-placeholder').remove();
147	        } else {
148	          var count = target.children('li').length;
149	          var placeholder = count + (count > 1 ? ' items' : ' item');
150	          target.after('<a href class="json-placeholder">' + placeholder + '</a>');
151	        }
152	        return false;
153	      });
154	
155	      // Simulate click on toggle button when placeholder is clicked
156	      $(this).on('click', 'a.json-placeholder', function() {
157	        $(this).siblings('a.json-toggle').click();
158	        return false;
159	      });
160	
161	      if (options.collapsed == true) {
162	        // Trigger click to collapse all nodes
163	        $(this).find('a.json-toggle').click();
164	      }
165	    });
166	  };
167	})(jQuery);

