     6	
     7	document.body.innerHTML = '<div id="json"></div>';
     8	
     9	test('withLinks option', () => {
    10	  const data = {
    11	    url: 'http://www.hello.com',
    12	  };
    13	  $('#json').jsonViewer(data, { withLinks: true });
    14	
    15	  expect($('#json').html()).toEqual(
    16	    '<a href="" class="json-toggle"></a>{<ul class="json-dict"><li>url: <a href="http://www.hello.com" class="json-string" target="_blank">http://www.hello.com</a></li></ul>}'
    17	  );
    18	
    19	  $('#json').jsonViewer(data, { withLinks: false });
    20	
    21	  expect($('#json').html()).toEqual(
    22	    '<a href="" class="json-toggle"></a>{<ul class="json-dict"><li>url: <span class="json-string">"http://www.hello.com"</span></li></ul>}'
    23	  );
    24	});
    25	
    26	test('withQuotes option', () => {
    27	  $('#json').jsonViewer({ 'hello': 'world' }, { withQuotes: false });
    28	
    29	  expect($('#json').html()).toEqual(
    30	    '<a href="" class="json-toggle"></a>{<ul class="json-dict"><li>hello: <span class="json-string">"world"</span></li></ul>}'
    31	  );
    32	
    33	  $('#json').jsonViewer({ 'hello': 'world' }, { withQuotes: true });
    34	
    35	  expect($('#json').html()).toEqual(
    36	    '<a href="" class="json-toggle"></a>{<ul class="json-dict"><li><span class="json-string">"hello"</span>: <span class="json-string">"world"</span></li></ul>}'
    37	  );
    38	});
    39	
