    44	 */
    45	function test_XSS(input) {
    46	  $('#json').jsonViewer(input);
    47	  scripts_in_json = $('#json script');
    48	  expect(scripts_in_json.length).toEqual(0);
    49	}
    50	
    51	test('XSS in object value', () => {
    52	  const input = {
    53	    key_1: '<script>alert(1)</script>'
    54	  };
    55	
    56	  test_XSS(input);
    57	});
    58	
    59	test('XSS in object key', () => {
